description:
Distill the design tokens out of a project's EXISTING CSS so new components match the app the user already built.

Use this when the user says "match our existing style", "use our design system", "style this like the rest of the app", or you are adding UI to a codebase that already has its own look. This is the inverse of find-design-system / create-design-system: instead of giving the user one of our systems, it reads theirs.

How to use it: read the project's `globals.css` (or wherever the design tokens / CSS custom properties live, e.g. a Tailwind v4 `@theme` block) and pass its full contents as `css`. For a one-file HTML page, pass the whole file as `css`: its `<style>` blocks are its design. The MCP server cannot read your filesystem, so you must paste the text.

Returns: the semantic palette (primary, background, foreground, accent, border, ring, etc.), radius, fonts, shadow scale, and spacing and type scale, plus a pasteable token sheet with every color normalized to `oklch()`. Handles hex, rgb()/rgba(), hsl()/hsla(), named colors, bare Shopify "r,g,b" triplets, and existing oklch values, across `:root`, `.dark`, and `@theme` blocks.

Beyond pasted CSS, `sources` accepts any mix of inputs and merges them (later sources win):
- kind "css": any stylesheet text, same as the `css` param.
- kind "computed": a JSON sample of rendered styles read off the LIVE site, which beats variable-name guessing because it records what elements actually look like. Gather it by running this in the site's browser console and passing the printed JSON:
```js
JSON.stringify((() => {
  const pick = (el, props) => {
    if (!el) return null;
    const cs = getComputedStyle(el);
    return Object.fromEntries(props.map((p) => [p, cs[p]]));
  };
  const clear = (c) => {
    const flat = (c || "").split(" ").join("");
    if (!flat || flat === "transparent") return true;
    // A fill under 10% opacity reads as no fill: Linear's ghost buttons sit at 2%. [BD-1468]
    const alpha = flat.match(/[,/]([0-9.]+%?)\)$/);
    if (!alpha || !/^(rgba|hsla)|\//.test(flat)) return false;
    const a = alpha[1].endsWith("%") ? parseFloat(alpha[1]) / 100 : parseFloat(alpha[1]);
    return a < 0.1;
  };
  // Any CSS colour as [r, g, b]. Chrome reports a colour authored in lab() or
  // oklch() in that form, so a 1px canvas converts what the regex cannot. [BD-1753]
  let canvas = null;
  const rgbOf = (c) => {
    const nums = String(c || "").startsWith("rgb") ? (c.match(/[0-9.]+/g) || []).slice(0, 3).map(Number) : [];
    if (nums.length === 3) return nums;
    try {
      canvas = canvas || document.createElement("canvas").getContext("2d");
      canvas.clearRect(0, 0, 1, 1);
      canvas.fillStyle = "#000";
      canvas.fillStyle = c;
      canvas.fillRect(0, 0, 1, 1);
      return Array.from(canvas.getImageData(0, 0, 1, 1).data.slice(0, 3));
    } catch {
      // No canvas, as in a test page: the colour counts as unreadable, not as an error.
      return null;
    }
  };
  // A colour as rgb() or rgba(), so the reader on our side can convert it:
  // Chrome reports a colour authored in lab() or oklch() in that form. [BD-1933]
  const asRgb = (c) => {
    const raw = String(c || "");
    if (!raw || raw.startsWith("rgb") || raw === "transparent") return raw;
    const rgb = rgbOf(raw);
    if (!rgb) return raw;
    const alpha = raw.match(/\/\s*([0-9.]+)(%?)\s*\)$/);
    const a = alpha ? parseFloat(alpha[1]) / (alpha[2] ? 100 : 1) : 1;
    return a < 1 ? "rgba(" + rgb.join(", ") + ", " + a + ")" : "rgb(" + rgb.join(", ") + ")";
  };
  const tint = (shadow) => String(shadow || "").replace(/(?:rgba?|hsla?|lab|lch|oklab|oklch|color)\([^)]*\)/g, asRgb);
  // True when a colour has no alpha, or an alpha of at least 0.9.
  const opaque = (c) => {
    const alpha = (String(c).match(/[0-9.]+%?/g) || [])[3];
    if (alpha === undefined) return true;
    return (alpha.endsWith("%") ? parseFloat(alpha) / 100 : parseFloat(alpha)) >= 0.9;
  };
  const spread = (c) => {
    const rgb = rgbOf(c);
    return rgb ? Math.max(...rgb) - Math.min(...rgb) : 0;
  };
  const luminance = (rgb) => {
    const [r, g, b] = rgb.map((v) => (v / 255 <= 0.03928 ? v / 255 / 12.92 : Math.pow((v / 255 + 0.055) / 1.055, 2.4)));
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  };
  const contrast = (a, b) => {
    const x = rgbOf(a);
    const y = rgbOf(b);
    if (!x || !y) return 1;
    const [hi, lo] = [luminance(x), luminance(y)].sort((p, q) => q - p);
    return (hi + 0.05) / (lo + 0.05);
  };
  const seen = (el) => {
    const box = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    return box.width > 0 && box.height > 0 && !(box.bottom <= 0) && !(box.right <= 0) && cs.opacity !== "0" && cs.visibility !== "hidden";
  };
  const ground = () => {
    const body = document.body ? getComputedStyle(document.body).backgroundColor : "";
    if (!clear(body)) return body;
    const html = document.documentElement ? getComputedStyle(document.documentElement).backgroundColor : "";
    return clear(html) ? "rgb(255, 255, 255)" : html;
  };
  // One pass over the visible page: how often each text colour and each
  // padding or gap length appears. [BD-1753] It also counts the shadows the
  // page draws, and weighs the first screen's text by its characters. [BD-1933]
  let walked = null;
  const walk = () => {
    if (walked) return walked;
    walked = { text: {}, texts: 0, space: {}, font: {}, shadow: {}, screenText: {}, gradient: {}, accent: {}, biggest: null };
    const fold = globalThis.innerHeight || 900;
    for (const el of Array.from(document.querySelectorAll("body *")).slice(0, 4000)) {
      if (!seen(el)) continue;
      const cs = getComputedStyle(el);
      if (cs.boxShadow && cs.boxShadow !== "none") walked.shadow[cs.boxShadow] = (walked.shadow[cs.boxShadow] || 0) + 1;
      const own = Array.from(el.childNodes || []).filter((n) => n.nodeType === 3).map((n) => String(n.textContent).trim()).join("");
      const box = el.getBoundingClientRect();
      const onScreen = box.top < fold;
      if (own && onScreen) walked.screenText[cs.color] = (walked.screenText[cs.color] || 0) + own.length;
      // The largest text on the first screen is the hero heading, whatever its tag.
      if (own && onScreen && (!walked.biggest || parseFloat(cs.fontSize) > walked.biggest.size)) walked.biggest = { el, size: parseFloat(cs.fontSize) };
      // Gradients the first screen paints, weighed by the area they cover.
      if (onScreen && String(cs.backgroundImage).includes("gradient(")) {
        walked.gradient[cs.backgroundImage] = (walked.gradient[cs.backgroundImage] || 0) + box.width * Math.min(box.height, fold);
      }
      // Colours that carry hue, from fills, text and icons: a brand's accents.
      const hued = (c) => !clear(c) && spread(c) >= 60;
      if (hued(cs.backgroundColor) && box.width * box.height < 600000) walked.accent[asRgb(cs.backgroundColor)] = (walked.accent[asRgb(cs.backgroundColor)] || 0) + 1;
      if (own && hued(cs.color)) walked.accent[asRgb(cs.color)] = (walked.accent[asRgb(cs.color)] || 0) + 1;
      if (cs.fill && cs.fill.startsWith("rgb") && hued(cs.fill)) walked.accent[asRgb(cs.fill)] = (walked.accent[asRgb(cs.fill)] || 0) + 1;
      for (const prop of ["paddingTop", "paddingRight", "paddingBottom", "paddingLeft", "rowGap", "columnGap"]) {
        const raw = String(cs[prop] || "");
        const px = parseFloat(raw);
        if (raw.endsWith("px") && px > 0) {
          const key = Math.round(px * 2) / 2 + "px";
          walked.space[key] = (walked.space[key] || 0) + 1;
        }
      }
      if (Array.from(el.childNodes || []).some((n) => n.nodeType === 3 && String(n.textContent).trim())) {
        walked.texts++;
        walked.text[cs.color] = (walked.text[cs.color] || 0) + 1;
        walked.font[cs.fontFamily] = (walked.font[cs.fontFamily] || 0) + 1;
      }
    }
    return walked;
  };
  // The fills a visitor sees on the first screen: a 16 by 10 grid of points,
  // each taking the first solid fill under it. A site often leaves body clear
  // and paints a dark page on a wrapper, as Mercury does. [BD-1933]
  let grid = null;
  const firstScreen = () => {
    if (grid) return grid;
    grid = { fills: {}, points: 160 };
    const w = globalThis.innerWidth;
    const h = globalThis.innerHeight;
    if (!w || !h || typeof document.elementsFromPoint !== "function") return grid;
    for (let i = 0; i < 16; i++) {
      for (let j = 0; j < 10; j++) {
        const under = document.elementsFromPoint(((i + 0.5) * w) / 16, ((j + 0.5) * h) / 10);
        const hit = under.find((el) => !el.closest(aside) && !clear(getComputedStyle(el).backgroundColor) && opaque(getComputedStyle(el).backgroundColor));
        if (!hit) continue;
        const fill = getComputedStyle(hit).backgroundColor;
        grid.fills[fill] = (grid.fills[fill] || 0) + 1;
      }
    }
    return grid;
  };
  // The page colour: the fill behind at least half the first screen, else the body's.
  const painted = () => {
    const top = Object.entries(firstScreen().fills).sort((a, b) => b[1] - a[1])[0];
    return top && top[1] >= firstScreen().points / 2 ? top[0] : ground();
  };
  const lum = (c) => {
    const rgb = rgbOf(c);
    return rgb ? luminance(rgb) : undefined;
  };
  // What the first screen paints. Light text over a light page means a layer
  // the page cannot report sits between, such as Postman's dark video hero:
  // the text says the scheme, and the darkest fill the grid saw, such as the
  // nav bar over that hero, gives its colour. [BD-1933]
  const screen = () => {
    const back = painted();
    const words = Object.entries(walk().screenText).sort((a, b) => b[1] - a[1]);
    const foreground = words[0] ? asRgb(words[0][0]) : undefined;
    const backLum = lum(back);
    if (backLum === undefined) return null;
    if (backLum < 0.125) return { scheme: "dark", background: asRgb(back), foreground };
    const textLum = foreground ? lum(foreground) : undefined;
    if (textLum === undefined || textLum < 0.42) return { scheme: "light", background: asRgb(back), foreground };
    // A fill must cover a twentieth of the grid to name the hero: a small
    // badge is not the colour behind the first screen.
    // A brand-coloured band, such as a red promo bar, is not the hero's colour,
    // so only a near-neutral fill counts.
    const darkest = Object.entries(firstScreen().fills)
      .filter(([c, n]) => n >= firstScreen().points / 20 && (lum(c) ?? 1) < 0.125 && spread(c) < 40)
      .map(([c]) => c)
      .sort((a, b) => (lum(a) ?? 1) - (lum(b) ?? 1))[0];
    return { scheme: "dark", background: darkest ? asRgb(darkest) : undefined, foreground };
  };
  const page = (props) => {
    const sample = pick(document.body, props);
    if (!sample) return sample;
    sample.backgroundColor = painted();
    // A body colour that almost no text renders in is an inherited default,
    // not the text colour: Stripe's body says black and its copy sets navy.
    // Take the frequent neutral text colour that stands out most. [BD-1753]
    const { text, texts, font } = walk();
    // The same holds for the font: Duolingo's body says sans-serif and its
    // copy sets duolingo-sans, so take the face most text renders in. [BD-1755]
    if (sample.fontFamily && texts >= 20 && (font[sample.fontFamily] || 0) < texts * 0.01) {
      const main = Object.entries(font).sort((a, b) => b[1] - a[1])[0];
      if (main && main[1] >= texts * 0.3) sample.fontFamily = main[0];
    }
    if (sample.color && texts >= 20 && (text[sample.color] || 0) < texts * 0.01) {
      const strong = Object.entries(text)
        .filter(([c, n]) => n >= texts * 0.05 && spread(c) < 80 && !c.includes("rgba") && !c.includes("/"))
        .sort((a, b) => contrast(b[0], sample.backgroundColor) - contrast(a[0], sample.backgroundColor))[0];
      if (strong) sample.color = strong[0];
    }
    return sample;
  };
  let picked = { main: null, paint: null, secondary: null, secondaryPaint: null };
  const aside = "dialog,[role=dialog],[aria-modal=true],[class*=cookie],[id*=cookie],[class*=consent],[id*=consent],[class*=cky-]";
  const action = (selector, props) => {
    // A call to action is often a link styled as a button with no class that
    // says so, as on Vercel and Linear, so filled links shaped like a button
    // count too. Those in the first screen come first. [BD-1753]
    // A wide cap: a hidden mega menu can hold hundreds of links before the hero.
    const all = Array.from(document.querySelectorAll(selector + ",a[href]")).slice(0, 1500).filter((el) => !el.closest(aside));
    const named = (el) => el.tagName !== "A" || !el.matches || el.matches(selector);
    const buttonShaped = (el) => {
      if (named(el)) return true;
      const box = el.getBoundingClientRect();
      return box.height >= 24 && box.height <= 72 && box.width <= 480 && String(el.textContent || "").trim() !== "";
    };
    // The layer that paints a button: the element itself, or a ::before or
    // ::after placed over its whole box, as on Duolingo's green link. [BD-1755]
    const layer = (el) => {
      const own = getComputedStyle(el);
      if (!clear(own.backgroundColor)) return own;
      const box = el.getBoundingClientRect();
      for (const which of ["::before", "::after"]) {
        const ps = getComputedStyle(el, which);
        if (!ps || !ps.content || ps.content === "none" || ps.content === "normal" || clear(ps.backgroundColor)) continue;
        if (ps.position !== "absolute") continue;
        // A layer nobody can see paints nothing. [BD-1755]
        if (ps.display === "none" || ps.visibility === "hidden" || parseFloat(ps.opacity) === 0) continue;
        if (parseFloat(ps.width) >= box.width * 0.8 && parseFloat(ps.height) >= box.height * 0.8) return ps;
      }
      return own;
    };
    const fillOf = (el) => layer(el).backgroundColor;
    const filled = all.filter((el) => seen(el) && buttonShaped(el) && !clear(fillOf(el)));
    const fold = globalThis.innerHeight || 900;
    const first = (el) => el.getBoundingClientRect().top < fold;
    const shown = [...filled.filter(first), ...filled.filter((el) => !first(el))];
    const isPrimaryClass = (t) => t === "primary" || ((t.startsWith("btn") || t.startsWith("button")) && t.endsWith("primary"));
    const primaryClass = shown.find((el) => String(el.className).split(" ").some(isPrimaryClass));
    const colourful = shown.slice(0, 12).reduce((best, el) => (spread(fillOf(el)) > (best ? spread(fillOf(best)) : 39) ? el : best), null);
    // With no colour to go by, the main button is the fill that stands out
    // most from the page: Vercel's black, not its white. [BD-1753]
    const backdrop = painted();
    // A see-through chip would read as its colour at full strength, so only solid fills compete.
    const standout = shown.slice(0, 12).filter((el) => opaque(fillOf(el))).reduce((best, el) => (contrast(fillOf(el), backdrop) > (best ? contrast(fillOf(best), backdrop) : 1) ? el : best), null);
    // The same fill often paints a small header button and the hero's larger
    // one, and the hero's carries the button's real shape. [BD-1753]
    const tallest = (el) =>
      el && shown.slice(0, 12).filter((o) => fillOf(o) === fillOf(el)).reduce((best, o) => (o.getBoundingClientRect().height > best.getBoundingClientRect().height ? o : best), el);
    const fallback = all.find(named) ?? null;
    const chosen = primaryClass ?? tallest(colourful ?? standout) ?? shown[0] ?? fallback;
    const sample = pick(chosen, props);
    if (!sample) return sample;
    // A painting layer carries the fill and the corners; the text colour stays the element's.
    const paint = layer(chosen);
    // The secondary button: the next first-screen button with another fill, or
    // an outline. A named button beats a link shaped like one. [BD-1933]
    const outlined = (el) => {
      const cs = getComputedStyle(el);
      return parseFloat(cs.borderTopWidth) > 0 && cs.borderTopStyle !== "none" && !clear(cs.borderTopColor);
    };
    const others = all.filter((el) => el !== chosen && seen(el) && buttonShaped(el) && first(el) && fillOf(el) !== fillOf(chosen) && (!clear(fillOf(el)) || outlined(el)));
    const secondary = others.find(named) ?? others[0] ?? null;
    // A secondary button can be painted by a layer too, so its layer is kept as the main one's is.
    picked = { main: chosen, paint, secondary, secondaryPaint: secondary ? layer(secondary) : null };
    // A square layer stays square unless the element clips it to its own corners. [BD-1755]
    const overflow = getComputedStyle(chosen).overflow;
    const clips = Boolean(overflow) && overflow !== "visible";
    for (const p of ["backgroundColor", "borderRadius", "cornerShape"]) {
      if (p in sample && paint[p] && !(p === "borderRadius" && clips && parseFloat(paint[p]) === 0)) sample[p] = paint[p];
    }
    return { ...sample, namedPrimary: primaryClass ? "yes" : "" };
  };
  const spacing = () => Object.entries(walk().space).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([length]) => length);
  // The page's own box shadows, most used first. [BD-1933]
  const shadows = () => Object.entries(walk().shadow).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([value]) => tint(value));
  const side = (cs) => {
    const [t, r, b, l] = [cs.paddingTop, cs.paddingRight, cs.paddingBottom, cs.paddingLeft];
    if (t === r && r === b && b === l) return t;
    return t === b && r === l ? t + " " + r : [t, r, b, l].join(" ");
  };
  const styleOf = (el, paint) => {
    if (!el) return null;
    const cs = getComputedStyle(el);
    const fill = paint || cs;
    // A layer that paints the button, such as Duolingo's ::before, also
    // carries its edge and its shadow when the element draws none. [BD-1933]
    const bare = parseFloat(cs.borderTopWidth) === 0 && parseFloat(cs.borderBottomWidth) === 0;
    const edge = fill !== cs && bare ? fill : cs;
    const shadow = cs.boxShadow === "none" ? fill.boxShadow : cs.boxShadow;
    return {
      backgroundColor: asRgb(fill.backgroundColor),
      color: asRgb(cs.color),
      borderColor: asRgb(edge.borderTopColor),
      borderWidth: edge.borderTopWidth,
      borderStyle: edge.borderTopStyle,
      // A square layer stays square unless the element clips it to its own corners, as action() reads it.
      borderRadius: fill !== cs && parseFloat(fill.borderRadius) === 0 && cs.overflow && cs.overflow !== "visible" ? cs.borderRadius : fill.borderRadius,
      padding: side(cs),
      fontSize: cs.fontSize,
      fontWeight: String(cs.fontWeight),
      boxShadow: tint(shadow),
      textTransform: cs.textTransform,
      letterSpacing: cs.letterSpacing,
      // A raised edge, such as Duolingo's, is a thicker bottom border.
      borderBottom: edge.borderBottomWidth !== edge.borderTopWidth ? [edge.borderBottomWidth, edge.borderBottomStyle, asRgb(edge.borderBottomColor)].join(" ") : "",
    };
  };
  // The hero heading's type, and whether it sits centred on the screen.
  const headingStyle = () => {
    const el = walk().biggest && walk().biggest.el;
    if (!el) return null;
    const cs = getComputedStyle(el);
    const box = el.getBoundingClientRect();
    const w = globalThis.innerWidth || 1280;
    const centred = cs.textAlign === "center" || (Math.abs(box.left + box.width / 2 - w / 2) < w * 0.05 && box.width < w * 0.7);
    return {
      color: asRgb(cs.color),
      fontFamily: String(cs.fontFamily || "").split(",")[0].trim().replace(/^["']|["']$/g, ""),
      fontSize: cs.fontSize,
      fontWeight: String(cs.fontWeight),
      letterSpacing: cs.letterSpacing,
      lineHeight: cs.lineHeight,
      textTransform: cs.textTransform,
      align: centred ? "center" : "left",
    };
  };
  const ranked = (counts, n) => Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, n).map(([value]) => value);
  // The first visible element a selector finds that passes a test, outside cookie banners.
  const firstOf = (selector, test) =>
    Array.from(document.querySelectorAll(selector)).slice(0, 400).find((el) => seen(el) && !el.closest(aside) && test(el, getComputedStyle(el))) ?? null;
  // How the main components look, read the way a visitor sees them. A card is
  // a box that stands apart from the page by a fill, a border or a shadow;
  // a nav link is a header link with no fill of its own. [BD-1933]
  const components = () => {
    try {
      const card = firstOf("[class*=card],article,li,section > div", (el, cs) => {
        const box = el.getBoundingClientRect();
        if (box.width < 160 || box.height < 100 || box.width > (globalThis.innerWidth || 1280) * 0.7) return false;
        const fill = !clear(cs.backgroundColor) && cs.backgroundColor !== painted();
        const edge = parseFloat(cs.borderTopWidth) > 0 && cs.borderTopStyle !== "none" && !clear(cs.borderTopColor);
        return fill || edge || (cs.boxShadow && cs.boxShadow !== "none");
      });
      const input = firstOf("input:not([type=hidden]):not([type=checkbox]):not([type=radio]),textarea,select", () => true);
      // The colour most top-bar links share: the first link found can sit in
      // a closed menu panel with a colour of its own. [BD-1933]
      const bar = Array.from(document.querySelectorAll("nav a[href],header a[href]")).slice(0, 400).filter((el) => {
        if (!seen(el) || el.closest(aside) || el === picked.main || el === picked.secondary) return false;
        const box = el.getBoundingClientRect();
        return box.top >= 0 && box.top < 150 && String(el.textContent || "").trim().length >= 2 && clear(getComputedStyle(el).backgroundColor);
      });
      const votes = {};
      for (const el of bar) votes[getComputedStyle(el).color] = (votes[getComputedStyle(el).color] || 0) + 1;
      const common = ranked(votes, 1)[0];
      const navLink = bar.find((el) => getComputedStyle(el).color === common) ?? null;
      return {
        button: styleOf(picked.main, picked.paint),
        secondaryButton: styleOf(picked.secondary, picked.secondaryPaint),
        card: styleOf(card),
        input: styleOf(input),
        navLink: styleOf(navLink),
        heading: headingStyle(),
      };
    } catch {
      // A page that breaks a read still gives its tokens.
      return null;
    }
  };
  const safely = (read) => {
    try {
      return read();
    } catch {
      return null;
    }
  };
  return {
    body: page(["backgroundColor","color","fontFamily"]),
    heading: pick(document.querySelector("h1,h2"), ["fontFamily"]),
    link: pick(document.querySelector("p a[href]"), ["color"]),
    button: action("button,[role=button],.btn,input[type=submit],a[class*=button],a[class*=btn]", ["backgroundColor","color","borderRadius","cornerShape"]),
    input: pick(document.querySelector("input:not([type=hidden]),textarea,select"), ["borderColor","borderRadius"]),
    card: pick(document.querySelector("[class*=card]"), ["backgroundColor","color","borderRadius","boxShadow","cornerShape"]),
    spacing: spacing(),
    components: components(),
    shadows: safely(shadows),
    screen: safely(screen),
    gradients: safely(() => ranked(walk().gradient, 3).map(tint)),
    accents: safely(() => ranked(walk().accent, 6)),
  };
})())
```
- kind "tokens": a design-tokens JSON export ($value entries, W3C format or the Figma variables API shape with 0..1 rgb floats).

Common vendor names (Shopify's --color-button family) are mapped into empty semantic slots automatically and the mapping is reported in the output.
